#include <stdio.h>
int main(){
    int head = 50;
    int req[5] = {55,58,39,18,90};
    int total = 0;
    int prev = head;
    for(int i=0;i<5;i++){
        total += (req[i]>prev? req[i]-prev : prev-req[i]);
        prev = req[i];
    }
    printf("FCFS total movement = %d cylinders\n", total);
    return 0;
}
